function dimensions(rows: number, columns: number) {
  if (![rows, columns].every((n) => Number.isInteger(n) && n >= 0 && n <= 50))
    throw new RangeError("Dimensions must be integers from 0 to 50");
}
export function* boardRows(rows: number, columns: number): Generator<number[]> {
  dimensions(rows, columns);
  for (let row = 0; row < rows; row++)
    yield Array.from(
      { length: columns },
      (_, column) => row * columns + column,
    );
}
export function createBoard(rows: number, columns: number): number[][] {
  return Array.from(boardRows(rows, columns));
}

