import random
def dimensions(rows, columns):
    if any(type(n) is not int or not 0 <= n <= 50 for n in (rows, columns)):
        raise ValueError("Dimensions must be integers from 0 to 50")
def seeded(seed):
    value = seed & 0xffffffff
    def random():
        nonlocal value
        value = (value * 1664525 + 1013904223) & 0xffffffff
        return value / 4294967296
    return random
def create_matrix(rows, columns, k, rng=random.random):
    dimensions(rows, columns)
    n = rows * columns
    if type(k) is not int or not 0 <= k <= n:
        raise ValueError("k must fit the matrix")
    pool = list(range(n))
    for i in range(n - 1, 0, -1):
        j = int(rng() * (i + 1))
        pool[i], pool[j] = pool[j], pool[i]
    chosen = set(pool[:k])
    return [[0 if r * columns + c in chosen else 1 for c in range(columns)] for r in range(rows)]

