function dimensions(rows: number, columns: number) {
  if (![rows, columns].every((n) => Number.isInteger(n) && n >= 0 && n <= 50))
    throw new RangeError("Dimensions must be integers from 0 to 50");
}
export function seeded(seed: number) {
  let value = seed >>> 0;
  return () => {
    value = (Math.imul(value, 1664525) + 1013904223) >>> 0;
    return value / 4294967296;
  };
}
export function createMatrix(
  rows: number,
  columns: number,
  k: number,
  random: () => number = Math.random,
): number[][] {
  dimensions(rows, columns);
  const n = rows * columns;
  if (!Number.isInteger(k) || k < 0 || k > n)
    throw new RangeError("k must fit the matrix");
  const pool = Array.from({ length: k }, (_, i) => i);
  if (k > 0)
    for (let i = k; i < n; i++) {
      const j = Math.floor(random() * (i + 1));
      if (j < k) pool[j] = i;
    }
  const chosen = new Set(pool);
  return Array.from({ length: rows }, (_, r) =>
    Array.from({ length: columns }, (_, c) =>
      chosen.has(r * columns + c) ? 0 : 1,
    ),
  );
}

