export type Token = "R" | "Y";
export type Cell = Token | null;
export type Game = {
  cells: Cell[][];
  player: Token;
  winner: Token | null;
  draw: boolean;
  moves: number;
};
export const ROWS = 5,
  COLUMNS = 5;
export function createGame(): Game {
  return {
    cells: Array.from({ length: ROWS }, () => Array<Cell>(COLUMNS).fill(null)),
    player: "R",
    winner: null,
    draw: false,
    moves: 0,
  };
}
export function boardOf(game: Game): Cell[][] {
  return game.cells;
}
function winnerAt(board: Cell[][], row: number, column: number): Token | null {
  void row;
  void column;
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLUMNS; c++) {
      const token = board[r][c];
      if (!token) continue;
      for (const [dr, dc] of [
        [0, 1],
        [1, 0],
      ]) {
        if (r + 3 * dr >= ROWS || c + 3 * dc >= COLUMNS) continue;
        if ([1, 2, 3].every((i) => board[r + i * dr][c + i * dc] === token))
          return token;
      }
    }
  return null;
}
export function move(game: Game, row: number, column: number): Game {
  if (
    game.winner ||
    game.draw ||
    !Number.isInteger(row) ||
    !Number.isInteger(column) ||
    row < 0 ||
    row >= ROWS ||
    column < 0 ||
    column >= COLUMNS
  )
    return game;
  const current = boardOf(game);
  if (current[row][column] !== null) return game;
  const cells = current.map((line, r) =>
    r === row
      ? line.map((value, c) => (c === column ? game.player : value))
      : line,
  );
  const board = cells;
  const winner = winnerAt(board, row, column);
  const moves = game.moves + 1;
  const draw = !winner && moves === ROWS * COLUMNS;
  return {
    cells,
    winner,
    draw,
    moves,
    player: winner || draw ? game.player : game.player === "R" ? "Y" : "R",
  };
}

