    cells: Array.from({ length: ROWS }, () => Array<Cell>(COLUMNS).fill(null)),
    player: "R",
    winner: null,
    draw: false,
    moves: 0,
  };
}
export function boardOf(game: Game): Cell[][] {
  return game.cells;
}
function winnerAt(board: Cell[][], row: number, column: number): Token | null {
  const token = board[row][column];
  for (const [dr, dc] of [
    [0, 1],
    [1, 0],
  ]) {
    let count = 1;
    for (const sign of [-1, 1]) {
      let r = row + dr * sign,
        c = column + dc * sign;
      while (
        r >= 0 &&
        r < ROWS &&
        c >= 0 &&
        c < COLUMNS &&
        board[r][c] === token
      ) {
        count++;
        r += dr * sign;
        c += dc * sign;
      }
    }
    if (count >= 4) return token;
  }
  return null;
}
export function move(game: Game, row: number, column: number): Game {
  if (
    game.winner ||
    game.draw ||
    !Number.isInteger(row) ||
    !Number.isInteger(column) ||
    row < 0 ||
    row >= ROWS ||
    column < 0 ||
    column >= COLUMNS
