    return game;
  const current = boardOf(game);
  if (current[row][column] !== null) return game;
  const cells = current.map((line, r) =>
    r === row
      ? line.map((value, c) => (c === column ? game.player : value))
      : line,
  );
  const board = cells;
  const winner = winnerAt(board, row, column);
  const moves = game.moves + 1;
  const draw = !winner && moves === ROWS * COLUMNS;
  return {
    cells,
    winner,
    draw,
    moves,
    player: winner || draw ? game.player : game.player === "R" ? "Y" : "R",
  };
}

