    cells: Array.from({ length: COLUMNS }, () => []),
    player: "R",
    winner: null,
    draw: false,
    moves: 0,
  };
}
export function boardOf(game: Game): Cell[][] {
  return Array.from({ length: ROWS }, (_, r) =>
    Array.from(
      { length: COLUMNS },
      (_, c) => game.cells[c][ROWS - 1 - r] ?? null,
    ),
  );
}
const windowsByCell: number[][][] = Array.from(
  { length: ROWS * COLUMNS },
  () => [],
);
for (let r = 0; r < ROWS; r++)
  for (let c = 0; c < COLUMNS; c++) {
    for (const [dr, dc] of [
      [0, 1],
      [1, 0],
    ]) {
      if (r + 3 * dr >= ROWS || c + 3 * dc >= COLUMNS) continue;
      const window = Array.from(
        { length: 4 },
        (_, i) => (r + i * dr) * COLUMNS + c + i * dc,
      );
      for (const index of window) windowsByCell[index].push(window);
    }
  }
function winnerAt(board: Cell[][], row: number, column: number): Token | null {
  const token = board[row][column];
  return windowsByCell[row * COLUMNS + column].some((window) =>
    window.every(
      (index) => board[Math.floor(index / COLUMNS)][index % COLUMNS] === token,
    ),
  )
    ? token
    : null;
}
export function move(game: Game, row: number, column: number): Game {
  if (
    game.winner ||
    game.draw ||
    !Number.isInteger(row) ||
    !Number.isInteger(column) ||
    row < 0 ||
    row >= ROWS ||
    column < 0 ||
    column >= COLUMNS
  )
    return game;
  const current = boardOf(game);
  row = ROWS - 1;
  while (row >= 0 && current[row][column] !== null) row--;
  if (row < 0) return game;
  const cells = game.cells.map((stack, c) =>
    c === column ? [...stack, game.player] : stack,
  );
  const board = boardOf({ ...game, cells });
  const winner = winnerAt(board, row, column);
  const moves = game.moves + 1;
  const draw = !winner && moves === ROWS * COLUMNS;
  return {
    cells,
    winner,
    draw,
    moves,
    player: winner || draw ? game.player : game.player === "R" ? "Y" : "R",
  };
}

