ROWS, COLUMNS = 6, 7

def create_game():
    return {"cells": [[] for _ in range(COLUMNS)], "player": "R", "winner": None, "draw": False, "moves": 0}

def board_of(game):
    return [[game["cells"][c][ROWS - 1 - r] if ROWS - 1 - r < len(game["cells"][c]) else None for c in range(COLUMNS)] for r in range(ROWS)]
WINDOWS_BY_CELL = [[] for _ in range(ROWS * COLUMNS)]
for r in range(ROWS):
    for c in range(COLUMNS):
        for dr, dc in ((0, 1), (1, 0)):
            if r + 3 * dr < ROWS and c + 3 * dc < COLUMNS:
                window = [(r + i * dr) * COLUMNS + c + i * dc for i in range(4)]
                for index in window:
                    WINDOWS_BY_CELL[index].append(window)

def winner_at(board, row, column):
    token = board[row][column]
    for window in WINDOWS_BY_CELL[row * COLUMNS + column]:
        if all(board[index // COLUMNS][index % COLUMNS] == token for index in window):
            return token
    return None
def move(game, row, column):
    if game["winner"] or game["draw"] or type(row) is not int or type(column) is not int or not 0 <= row < ROWS or not 0 <= column < COLUMNS:
        return game
    current = board_of(game)
    row = ROWS - 1
    while row >= 0 and current[row][column] is not None:
        row -= 1
    if row < 0:
        return game
    cells = [stack + [game["player"]] if c == column else stack for c, stack in enumerate(game["cells"])]
    board = board_of({**game, "cells": cells})
    winner = winner_at(board, row, column)
    moves = game["moves"] + 1
    draw = winner is None and moves == ROWS * COLUMNS
    return {"cells": cells, "winner": winner, "draw": draw, "moves": moves, "player": game["player"] if winner or draw else ("Y" if game["player"] == "R" else "R")}

