export type Row = { id: string; name: string; depth: number };
export function toggleLocal(expanded: boolean, node: FileNode): boolean {
  return node.type === "folder" ? !expanded : expanded;
}
export function visibleRows(
  nodes: FileNode[],
  expanded: ReadonlySet<string>,
  depth = 0,
): Row[] {
  return nodes.flatMap((node) => [
    { id: node.id, name: node.name, depth },
    ...(node.type === "folder" && expanded.has(node.id)
      ? visibleRows(node.children, expanded, depth + 1)
      : []),
  ]);
}

