/model.ts.code:
export type FileNode =
  | { id: string; name: string; type: "file" }
  | { id: string; name: string; type: "folder"; children: FileNode[] };
export type Row = { id: string; name: string; depth: number };
export type NormalTree = {
  roots: string[];
  nodes: Record<
    string,
    { id: string; name: string; type: "file" | "folder"; children: string[] }
  >;
};
export function normalize(input: FileNode[]): NormalTree {
  const tree: NormalTree = {
    roots: input.map((node) => node.id),
    nodes: Object.create(null),
  };
  function visit(node: FileNode) {
    if (Object.hasOwn(tree.nodes, node.id))
      throw new Error("IDs must be globally unique");
    tree.nodes[node.id] = {
      id: node.id,
      name: node.name,
      type: node.type,
      children:
        node.type === "folder" ? node.children.map((child) => child.id) : [],
    };
    if (node.type === "folder") node.children.forEach(visit);
  }
  input.forEach(visit);
  return tree;
}
export function toggle(
  expanded: ReadonlySet<string>,
  node: { id: string; type: string },
): Set<string> {
  const next = new Set(expanded);
  if (node.type !== "folder") return next;
  if (next.has(node.id)) next.delete(node.id);
  else next.add(node.id);
  return next;
}
export function visibleRows(
  tree: NormalTree,
  expanded: ReadonlySet<string>,
): Row[] {
  const rows: Row[] = [];
  function visit(id: string, depth: number) {
    const node = tree.nodes[id];
    rows.push({ id, name: node.name, depth });
    if (node.type === "folder" && expanded.has(id))
      node.children.forEach((child) => visit(child, depth + 1));
  }
  tree.roots.forEach((id) => visit(id, 0));
  return rows;
}

