def normalize(input_nodes):
    tree = {"roots": [node["id"] for node in input_nodes], "nodes": {}}
    def visit(node):
        if node["id"] in tree["nodes"]:
            raise ValueError("IDs must be globally unique")
        children = node.get("children", []) if node["type"] == "folder" else []
        tree["nodes"][node["id"]] = {**node, "children": [child["id"] for child in children]}
        for child in children:
            visit(child)
    for node in input_nodes:
        visit(node)
    return tree

def toggle(expanded, node):
    next_ids = set(expanded)
    if node["type"] == "folder":
        if node["id"] in next_ids:
            next_ids.remove(node["id"])
        else:
            next_ids.add(node["id"])
    return next_ids

def visible_rows(tree, expanded):
    rows = []
    def visit(node_id, depth):
        node = tree["nodes"][node_id]
        rows.append({"id": node_id, "name": node["name"], "depth": depth})
        if node["type"] == "folder" and node_id in expanded:
            for child in node["children"]:
                visit(child, depth + 1)
    for root in tree["roots"]:
        visit(root, 0)
    return rows

