export type Option = { id: string; label: string; disabled?: boolean };
export type State = { selected: string[]; query: string; open: boolean };
export type Action =
  | { type: "query"; value: string }
  | { type: "open" | "close" }
  | { type: "select" | "remove"; id: string };
export function initialState(): State {
  return { selected: [], query: "", open: false };
}
export function visibleOptions(options: Option[], state: State): Option[] {
  const selected = new Set(state.selected),
    query = state.query.toLowerCase();
  return options.filter(
    (option) =>
      !selected.has(option.id) && option.label.toLowerCase().includes(query),
  );
}
export function selectIds(
  selected: string[],
  id: string,
  options: Option[],
): string[] {
  const option = options.find((item) => item.id === id);
  return !option || option.disabled || selected.includes(id)
    ? selected
    : [...selected, id];
}
export function reduce(state: State, action: Action, options: Option[]): State {
  switch (action.type) {
    case "query":
      return { ...state, query: action.value, open: true };
    case "open":
      return { ...state, open: true };
    case "close":
      return { ...state, open: false };
    case "remove":
      return {
        ...state,
        selected: state.selected.filter((id) => id !== action.id),
      };
    case "select": {
      const selected = selectIds(state.selected, action.id, options);
      return selected === state.selected
        ? state
        : { selected, query: "", open: true };
    }
  }
}

