def initial_state():
    return {"selected": [], "query": "", "open": False}

def visible_options(options, state):
    selected, query = set(state["selected"]), state["query"].lower()
    return [option for option in options if option["id"] not in selected and query in option["label"].lower()]

def select_ids(selected, option_id, options):
    option = next((item for item in options if item["id"] == option_id), None)
    if option is None or option.get("disabled", False) or option_id in selected:
        return selected
    return selected + [option_id]

def reduce(state, action, options):
    kind = action["type"]
    if kind == "query":
        return {**state, "query": action["value"], "open": True}
    if kind in ("open", "close"):
        return {**state, "open": kind == "open"}
    if kind == "remove":
        return {**state, "selected": [item for item in state["selected"] if item != action["id"]]}
    if kind == "select":
        selected = select_ids(state["selected"], action["id"], options)
        return state if selected is state["selected"] else {"selected": selected, "query": "", "open": True}
    raise ValueError("Unknown action")
class SelectionController:
    """Parent-owned state; a UI can subscribe through on_change."""
    def __init__(self, options, on_change=lambda state: None):
        self.options, self.on_change, self.state = options, on_change, initial_state()

    def dispatch(self, action):
        self.state = reduce(self.state, action, self.options)
        self.on_change(self.state)
        return self.state

