import asyncio
from urllib.parse import quote

class Cancelled(Exception):
    pass

class Cancellation:
    def __init__(self):
        self.cancelled = False
    def cancel(self):
        self.cancelled = True
    def check(self):
        if self.cancelled:
            raise Cancelled("Cancelled")

async def get_json(url, fetcher, cancellation):
    cancellation.check()
    response = await fetcher(url, cancellation)
    cancellation.check()
    if not response["ok"]:
        raise ValueError(f'HTTP {response["status"]}')
    return response["data"]

async def count_repos(name, fetcher, cancellation):
    count, page = 0, 1
    while True:
        url = f'https://api.github.com/users/{quote(name, safe="")}/repos?type=owner&per_page=100&page={page}'
        data = await get_json(url, fetcher, cancellation)
        if not isinstance(data, list):
            raise ValueError("Expected a repository array")
        count += len(data)
        if len(data) < 100:
            return count
        page += 1

def place_users(names, rng):
    if len(names) > 3:
        raise ValueError("At most three users")
    cells, result = list(range(9)), []
    for i, name in enumerate(names):
        j = i + int(rng() * (9 - i))
        cells[i], cells[j] = cells[j], cells[i]
        result.append({"name": name, "cell": cells[i], "count": None, "error": None})
    return result

async def load_matrix(fetcher, rng, cancellation, on_update):
    data = await get_json("/userList", fetcher, cancellation)
    if not isinstance(data, list) or len(data) > 3 or any(not isinstance(item, dict) or not isinstance(item.get("name"), str) or not item["name"].strip() for item in data):
        raise ValueError("Expected up to three named users")
    unique = {item["name"].strip().lower(): item["name"].strip() for item in data}
    cells = place_users(list(unique.values()), rng)
    def publish():
        cancellation.check()
        on_update([dict(cell) for cell in cells])
    publish()
    async def load(index):
        try:
            count = await count_repos(cells[index]["name"], fetcher, cancellation)
            cancellation.check()
            cells[index] = {**cells[index], "count": count}
        except Cancelled:
            raise
        except Exception as error:
            cancellation.check()
            cells[index] = {**cells[index], "error": str(error)}
    for index in range(len(cells)):
        await load(index)
    publish()
    return cells

