import { useEffect, useState } from "react";
import { loadMatrix, seeded, UserCell } from "./model";
import { mockFetch } from "./mock";
import "./styles.css";
export default function App() {
  const [revision, setRevision] = useState(0);
  const [cells, setCells] = useState<UserCell[]>([]);
  const [status, setStatus] = useState("Loading");
  useEffect(() => {
    const controller = new AbortController();
    setStatus("Loading");
    setCells([]);
    loadMatrix(mockFetch, seeded(42 + revision), controller.signal, setCells)
      .then(() => {
        if (!controller.signal.aborted)
          setStatus("Loaded; errors remain attached to their users");
      })
      .catch((error) => {
        if (!controller.signal.aborted) setStatus(String(error));
      });
    return () => controller.abort();
  }, [revision]);
  return (
    <main>
      <h1>User repository matrix</h1>
      <p>
        Mock data: Ada has 103 public owned repositories; Grace fails; Linus has
        2.
      </p>
      <button onClick={() => setRevision((value) => value + 1)}>
        Reload users
      </button>
      <p role="status">{status}</p>
      <div
        className="grid"
        style={{ gridTemplateColumns: "repeat(3, minmax(0, 1fr))" }}
      >
        {Array.from({ length: 9 }, (_, index) => {
          const user = cells.find((item) => item.cell === index);
          return (
            <div className="cell user-cell" key={index}>
              {user ? (
                <span>
                  {user.name}:{" "}
                  {user.error ??
                    (user.count === null
                      ? "Loading"
                      : `${user.count} repositories`)}
                </span>
              ) : (
                "Empty"
              )}
            </div>
          );
        })}
      </div>
    </main>
  );
}

