export function seeded(seed: number) {
  let value = seed >>> 0;
  return () => {
    value = (Math.imul(value, 1664525) + 1013904223) >>> 0;
    return value / 4294967296;
  };
}
export type Fetcher = (
  url: string,
  init: { signal: AbortSignal },
) => Promise<Response>;
export type UserCell = {
  name: string;
  cell: number;
  count: number | null;
  error: string | null;
};
function check(signal: AbortSignal) {
  if (signal.aborted) throw new DOMException("Cancelled", "AbortError");
}
async function getJson(
  url: string,
  fetcher: Fetcher,
  signal: AbortSignal,
): Promise<unknown> {
  check(signal);
  const response = await fetcher(url, { signal });
  check(signal);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data: unknown = await response.json();
  check(signal);
  return data;
}
export async function countRepos(
  name: string,
  fetcher: Fetcher,
  signal: AbortSignal,
): Promise<number> {
  let count = 0;
  for (let page = 1; ; page++) {
    const url = `https://api.github.com/users/${encodeURIComponent(name)}/repos?type=owner&per_page=100&page=${page}`;
    const data = await getJson(url, fetcher, signal);
    if (!Array.isArray(data)) throw new Error("Expected a repository array");
    count += data.length;
    if (data.length < 100) return count;
  }
}
export function placeUsers(names: string[], random: () => number): UserCell[] {
  if (names.length > 3) throw new RangeError("At most three users");
  const cells = Array.from({ length: 9 }, (_, i) => i);
  return names.map((name, i) => {
    const j = i + Math.floor(random() * (9 - i));
    [cells[i], cells[j]] = [cells[j], cells[i]];
    return { name, cell: cells[i], count: null, error: null };
  });
}
export async function loadMatrix(
  fetcher: Fetcher,
  random: () => number,
  signal: AbortSignal,
  onUpdate: (cells: UserCell[]) => void,
): Promise<UserCell[]> {
  const data = await getJson("/userList", fetcher, signal);
  if (
    !Array.isArray(data) ||
    data.length > 3 ||
    data.some(
      (item) => !item || typeof item.name !== "string" || !item.name.trim(),
    )
  )
    throw new Error("Expected up to three named users");
  const names = [
    ...new Map(
      data.map((item) => [item.name.trim().toLowerCase(), item.name.trim()]),
    ).values(),
  ] as string[];
  const cells = placeUsers(names, random);
  function publish() {
    check(signal);
    onUpdate(cells.map((cell) => ({ ...cell })));
  }
  publish();
  async function load(index: number) {
    try {
      const count = await countRepos(cells[index].name, fetcher, signal);
      check(signal);
      cells[index] = { ...cells[index], count };
    } catch (error) {
      check(signal);
      cells[index] = {
        ...cells[index],
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }
  let next = 0;
  async function worker() {
    while (next < cells.length) {
      const index = next++;
      await load(index);
      publish();
    }
  }
  await Promise.all(
    Array.from({ length: Math.min(2, cells.length) }, () => worker()),
  );
  publish();
  return cells;
}

