import { Fetcher } from "./model";
export const mockFetch: Fetcher = async (url, { signal }) => {
  await new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(new DOMException("Cancelled", "AbortError"));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(new DOMException("Cancelled", "AbortError"));
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, 120);
    signal.addEventListener("abort", onAbort, { once: true });
  });
  if (url === "/userList")
    return new Response(
      JSON.stringify([{ name: "ada" }, { name: "grace" }, { name: "linus" }]),
    );
  const parsed = new URL(url),
    name = parsed.pathname.split("/")[2],
    page = Number(parsed.searchParams.get("page"));
  if (name === "grace")
    return new Response("Rate limited in this mock", { status: 429 });
  const total = name === "ada" ? 103 : 2;
  return new Response(
    JSON.stringify(
      Array.from(
        { length: Math.max(0, Math.min(100, total - (page - 1) * 100)) },
        (_, i) => ({ id: (page - 1) * 100 + i }),
      ),
    ),
  );
};

